(() => {
 'use strict';const RI=window.RI,esc=RI.esc,kinds={publication:'انتشار',payments:'پرداخت و خرید',support:'پشتیبانی',product:'خبرهای رزومیت'};
 const metrics=[['total','همهٔ اعلان‌ها','bell'],['unread','خوانده‌نشده','eye'],['seen','خوانده‌شده','check'],['recent','هفت روز اخیر','calendar']];
 RI.registerPage('notifications',{title:'اعلان‌ها',render(ctx){return RI.pageHead({title:ctx.opts?.tab==='unread'?'اعلان‌های خوانده‌نشده':'صندوق اعلان‌ها',actions:'<button type="button" class="btn btn--soft" data-read-all>'+RI.icon('check')+'خواندن همه</button>'})+'<section data-activity-summary aria-label="خلاصهٔ اعلان‌ها">'+RI.activitySummary(metrics)+'</section>'+RI.tabsHtml([['inbox','همهٔ اعلان‌ها'],['unread','خوانده‌نشده‌ها'],['preferences','تنظیم اعلان‌ها']],ctx.opts?.tab||'inbox')+'<div id="notification-tools"></div><div id="notification-body" aria-live="polite"></div>';},mount(root,ctx){
  const body=root.querySelector('#notification-body'),tools=root.querySelector('#notification-tools');let tab=ctx.opts?.tab==='preferences'?'preferences':'inbox',kind='',unread=ctx.opts?.tab==='unread',alive=true,next=null,rows=[],preferences={},serial=0;
  function controls(){tools.innerHTML=tab==='inbox'?'<div class="workspace-tools"><div class="field"><label class="field__label" for="notice-kind">موضوع</label><select class="select" id="notice-kind"><option value="">همهٔ موضوعات</option>'+Object.entries(kinds).map(([id,label])=>'<option value="'+id+'" '+(id===kind?'selected':'')+'>'+label+'</option>').join('')+'</select></div><button class="btn btn--ghost" type="button" data-refresh>'+RI.icon('refresh')+'به‌روزرسانی</button></div>':'';}
  function paint(){if(tab==='preferences'){body.innerHTML='<section class="workspace-band"><h2>اعلان‌های کوتاه داخل سایت</h2>'+Object.entries(kinds).map(([id,label])=>'<div class="syncrow"><b>'+label+'</b>'+RI.switchHtml({checked:preferences[id]!==false,label:'نمایش توست '+label}).replace('<input','<input data-notice-pref="'+id+'"')+'</div>').join('')+'<p class="field__hint">رویدادها در صندوق می‌مانند؛ این انتخاب فقط نمایش توست تازه را کنترل می‌کند. کانال‌های بیرون از سایت و اجازهٔ هر دستگاه را در بخش زیر مدیریت کن.</p><button class="btn btn--primary" type="button" data-save-notices>ذخیرهٔ انتخاب‌ها</button></section><div data-notification-channels></div>';RI.mountNotificationChannels(body.querySelector('[data-notification-channels]'));return;}
   body.innerHTML=rows.length?rows.map(item=>'<article class="notification-item '+(!item.read_at?'is-unread':'')+'"><small>'+esc(kinds[item.kind]||'اعلان')+' · '+RI.date(Number(item.created_at))+'</small><h2>'+esc(item.title)+'</h2><p>'+esc(item.body)+'</p><div class="btnrow"><a class="btn btn--soft btn--sm" href="'+esc(item.url)+'">مشاهدهٔ جزئیات'+RI.icon('chevL')+'</a>'+(!item.read_at?'<button class="btn btn--ghost btn--sm" type="button" data-read="'+item.id+'">خواندم</button>':'<span class="chip">خوانده‌شده</span>')+'</div></article>').join('')+(next?'<button class="btn btn--soft" type="button" data-more>اعلان‌های قبلی</button>':''):RI.empty({icon:'bell',title:'اعلان تازه‌ای نیست'});
  }
  async function load(more=false){const request=++serial;if(!more)body.innerHTML='<p role="status">در حال دریافت اعلان‌ها…</p>';try{const result=await RI.dashboardRequest('notifications?'+new URLSearchParams({kind,unread:unread?'1':'0',...(more&&next?{before:next}:{})}));if(!alive||request!==serial)return;root.querySelector('[data-activity-summary]').innerHTML=RI.activitySummary(metrics,result.summary);rows=more?rows.concat(result.rows):result.rows;preferences=result.preferences;next=result.next;RI.inbox=result;RI.emit('inbox');paint();}catch(e){if(alive)body.innerHTML='<p role="alert">'+esc(e.message)+'</p><button class="btn" data-refresh>تلاش دوباره</button>';}}
  RI.delegate(root,'click','[data-workspace-tab]',(e,b)=>RI.go('notifications',b.dataset.workspaceTab==='inbox'?{}:{tab:b.dataset.workspaceTab}));
  tools.addEventListener('change',e=>{if(e.target.id==='notice-kind')kind=e.target.value;load();});RI.delegate(root,'click','[data-refresh]',()=>load());RI.delegate(root,'click','[data-more]',()=>load(true));
  async function read(id){try{await RI.dashboardRequest('notifications/read',id?{id}:{});await load();RI.emit('inbox');}catch(e){RI.toast(e.message,{kind:'error'});}}
  RI.delegate(root,'click','[data-read]',(e,b)=>read(b.dataset.read));RI.delegate(root,'click','[data-read-all]',()=>read());RI.delegate(root,'click','[data-save-notices]',async(e,b)=>{b.disabled=true;const values={};root.querySelectorAll('[data-notice-pref]').forEach(x=>values[x.dataset.noticePref]=x.checked);try{await RI.dashboardRequest('notifications/preferences',values);preferences=values;RI.toast('تنظیم اعلان‌ها ذخیره شد');}catch(error){RI.toast(error.message,{kind:'error'});}finally{b.disabled=false;}});
  controls();load();return()=>{alive=false;};
 }});
})();
